//! Test vectors for the SHA2 hash funtions.
//! See: https://datatracker.ietf.org/doc/html/rfc6234#section-8.5

mod common;

use common::proofs::test_proof;
use zkboo::{
    backend::{Backend, Frontend},
    circuit::Circuit,
    // crypto::{HashPRG, Hasher},
    executor::{OwnedFlexibleWordPool, exec},
};
use zkboo_sha2::{
    sha256::{sha224bytes, sha256bytes},
    sha512::{sha384bytes, sha512bytes},
};
use zkboo::executor::ExecOptions;

trait Sha2Circuit: Circuit {
    fn new(msg: Vec<u8>) -> Self;
}

macro_rules! sha2_circuit {
    ($name: ident, $func: ident) => {
        struct $name {
            msg: Vec<u8>,
        }

        impl Circuit for $name {
            fn exec<B: Backend>(&self, frontend: &Frontend<B>) {
                let msg = self
                    .msg
                    .iter()
                    .map(|&b| frontend.input(b))
                    .collect::<Vec<_>>();
                let output = $func(frontend.allocator(), msg);
                output.into_iter().for_each(|b| frontend.output(b));
            }
        }

        impl Sha2Circuit for $name {
            fn new(msg: Vec<u8>) -> Self {
                return Self { msg };
            }
        }
    };
}

fn run_sha_test<C: Sha2Circuit + Sync>(test_vectors: &[(&[u8], usize, &[u8])]) {
    type WP = OwnedFlexibleWordPool<u8>;
    for (msg, repeat, expected) in test_vectors {
        let msg = msg.repeat(*repeat);
        let circuit = C::new(msg.clone());
        let output = exec::<_, WP, _>(&circuit, ExecOptions::new()).u8;
        let expected: Vec<u8> = expected.to_vec();
        assert_eq!(output, expected, "on input {:?}", msg);
        test_proof(&circuit);
    }
}

